package com.ncpl.sales.cashflow.service;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.ncpl.sales.cashflow.entity.InvoiceEntity;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.math.BigDecimal;import java.time.*;import java.util.*;import java.nio.file.*;
class LiveCashPlanTermsTest {
 @TempDir Path folder;
 TallyLiveService tally=mock(TallyLiveService.class);ObjectMapper mapper=new ObjectMapper();
 BigDecimal n(String s){return new BigDecimal(s);}
 LiveCashPlanTerms reader()throws Exception{when(tally.getServerUrl()).thenReturn("http://mock:9000");when(tally.cashPlanCompanyName()).thenReturn("Company");when(tally.cashPlanConfiguredCompany()).thenReturn("Company");LiveCashPlanTerms r=new LiveCashPlanTerms(tally,mapper);org.springframework.test.util.ReflectionTestUtils.setField(r,"cacheFile",folder.resolve("cache.json").toString());return r;}
 InvoiceEntity bill(String number,String amount){InvoiceEntity b=new InvoiceEntity("Customer",number,LocalDate.of(2026,9,21),LocalDate.of(2026,11,5),n(amount),InvoiceEntity.InvoiceType.INFLOW,"TALLY");b.setRetention(false);return b;}
 TallyLiveService.CashPlanVoucher voucher(String id,String number,double basic){TallyLiveService.CashPlanVoucher v=new TallyLiveService.CashPlanVoucher();v.masterId=id;v.alterId="1";v.number=number;v.party="Customer";v.date=LocalDate.of(2026,9,21);v.narration="85% Payment Along With 100% GST Value as per PO Terms.85% On Basic + GST Full amount";v.ledgers=Arrays.asList(new TallyLiveService.LedgerLine("Customer",-basic*1.18,false),new TallyLiveService.LedgerLine("Supply Inter State 18%",basic,false),new TallyLiveService.LedgerLine("Output IGST @ 18%",basic*.18,true));return v;}
 void respond(List<TallyLiveService.CashPlanVoucher> vs)throws Exception{when(tally.cashPlanHeaders(anyString(),any(),any())).thenReturn(vs);when(tally.cashPlanAmounts(anyString(),anyList())).thenAnswer(call->{List<String> ids=call.getArgument(1);List<TallyLiveService.CashPlanVoucher> out=new ArrayList<>();for(TallyLiveService.CashPlanVoucher v:vs)if(ids.contains(v.masterId))out.add(v);return out;});}
 @Test void gstRateCommentAloneIsNotAPaymentTerm(){assertFalse(LiveCashPlanTerms.candidate("GST charged @ 18%"));assertTrue(LiveCashPlanTerms.candidate("85% basic plus full GST"));}
 @Test void recognizesPercentageOnBasicWithFullGstOnly(){assertEquals(0,n("85").compareTo(LiveCashPlanTerms.percent("85% BASIC + FULL GST")));assertEquals(0,n("85").compareTo(LiveCashPlanTerms.percent(voucher("1","A",1000).narration)));assertNull(LiveCashPlanTerms.percent("85% basic then 10% delivery + full GST"));assertNull(LiveCashPlanTerms.percent("85% of total"));assertNull(LiveCashPlanTerms.percent("100% basic + full GST"));}
 @Test void threeNewInvoicesNeedNoConfiguredInvoiceNumbers()throws Exception{LiveCashPlanTerms r=reader();respond(Arrays.asList(voucher("1","NEW-A",1000),voucher("2","NEW-B",2000),voucher("3","NEW-C",500)));LiveCashPlanTerms.Result result=r.resolve(Arrays.asList(bill("NEW-A","1180"),bill("NEW-B","2360"),bill("NEW-C","590")),Collections.emptyList());assertEquals("TALLY",result.source);assertEquals(3,result.rules.size());assertEquals(n("525.00"),result.rules.stream().map(CashPlanPaymentTerms.Rule::held).reduce(BigDecimal.ZERO,BigDecimal::add));assertNull(result.warning);}
 @Test void changedNarrationIsDetectedEvenWithSameBalance()throws Exception{LiveCashPlanTerms r=reader();TallyLiveService.CashPlanVoucher v=voucher("1","NEW-A",1000);respond(Collections.singletonList(v));List<InvoiceEntity> bills=Collections.singletonList(bill("NEW-A","1180"));assertEquals(n("150.00"),r.resolve(bills,Collections.emptyList()).rules.get(0).held());v.alterId="2";v.narration="90% Basic + Full GST";assertEquals(n("100.00"),r.resolve(bills,Collections.emptyList()).rules.get(0).held());verify(tally,times(2)).cashPlanAmounts(anyString(),anyList());}
 @Test void removedTermsDoNotKeepOldConfiguredSplit()throws Exception{LiveCashPlanTerms r=reader();TallyLiveService.CashPlanVoucher v=voucher("1","NEW-A",1000);respond(Collections.singletonList(v));List<InvoiceEntity> bills=Collections.singletonList(bill("NEW-A","1180"));List<CashPlanPaymentTerms.Rule> old=r.resolve(bills,Collections.emptyList()).rules;v.alterId="2";v.narration="Payment on delivery";assertTrue(r.resolve(bills,old).rules.isEmpty());}
 @Test void unchangedVouchersReuseBasicGstAmountsButAlwaysCheckMetadata()throws Exception{LiveCashPlanTerms r=reader();respond(Collections.singletonList(voucher("1","A",1000)));List<InvoiceEntity> bills=Collections.singletonList(bill("A","1180"));r.resolve(bills,Collections.emptyList());r.resolve(bills,Collections.emptyList());verify(tally,times(2)).cashPlanHeaders(anyString(),any(),any());verify(tally,times(1)).cashPlanAmounts(anyString(),anyList());}
 @Test void multipleBasicLedgerLinesAreSummed(){InvoiceEntity b=bill("A","5598923");TallyLiveService.CashPlanVoucher v=voucher("1","A",1000);v.ledgers=Arrays.asList(new TallyLiveService.LedgerLine("Customer",-5598923,false),new TallyLiveService.LedgerLine("Supply Inter State 18%",3192536.50,false),new TallyLiveService.LedgerLine("Supply Inter State 18%",1552313.50,false),new TallyLiveService.LedgerLine("Output IGST @18%",854073,true));CashPlanPaymentTerms.Rule rule=LiveCashPlanTerms.derive(b,v,Collections.emptyList());assertNull(rule.reviewReason);assertEquals(n("711727.50"),rule.held());}
 @Test void unsupportedChargesRequireReviewInsteadOfTreatingThemAsBasic(){TallyLiveService.CashPlanVoucher v=voucher("1","A",1000);v.ledgers=new ArrayList<>(v.ledgers);v.ledgers.add(new TallyLiveService.LedgerLine("Freight",100,false));assertNotNull(LiveCashPlanTerms.derive(bill("A","1280"),v,Collections.emptyList()).reviewReason);}
 @Test void partialPaymentsNeedReviewRatherThanTakingFifteenPercentOfBalance(){CashPlanPaymentTerms.Rule rule=LiveCashPlanTerms.derive(bill("A","500"),voucher("1","A",1000),Collections.emptyList());CashPlanPaymentTerms terms=new CashPlanPaymentTerms(mapper);InvoiceEntity b=bill("A","500");assertTrue(terms.allocation(b,Collections.singletonList(b),Collections.singletonList(rule)).review);}
 @Test void readFailureUsesPersistedLastGoodCacheWithVisibleWarning()throws Exception{LiveCashPlanTerms r=reader();respond(Collections.singletonList(voucher("1","A",1000)));List<InvoiceEntity> bills=Collections.singletonList(bill("A","1180"));r.resolve(bills,Collections.emptyList());when(tally.cashPlanHeaders(anyString(),any(),any())).thenThrow(new java.io.IOException("offline"));LiveCashPlanTerms.Result cached=reader().resolve(bills,Collections.emptyList());assertEquals("CACHED",cached.source);assertEquals(n("150.00"),cached.rules.get(0).held());assertTrue(cached.warning.contains("NOT been verified"));}
 @Test void noPreviousCacheNeverPretendsNewCommentsWereChecked()throws Exception{LiveCashPlanTerms r=reader();when(tally.cashPlanHeaders(anyString(),any(),any())).thenThrow(new java.io.IOException("offline"));LiveCashPlanTerms.Result result=r.resolve(Collections.singletonList(bill("A","1180")),Collections.emptyList());assertEquals("CONFIG_ONLY",result.source);assertNotNull(result.warning);}
 @Test void ledgerBatchesAreLimitedToFive()throws Exception{LiveCashPlanTerms r=reader();List<TallyLiveService.CashPlanVoucher> vs=new ArrayList<>();List<InvoiceEntity> bills=new ArrayList<>();for(int i=1;i<=11;i++){vs.add(voucher(""+i,"A"+i,1000));bills.add(bill("A"+i,"1180"));}respond(vs);assertEquals(11,r.resolve(bills,Collections.emptyList()).rules.size());verify(tally,times(3)).cashPlanAmounts(eq("Company"),argThat(ids->ids.size()<=5));}
 @Test void aVoucherSharedByTwoBillReferencesIsNotSplitTwice()throws Exception{LiveCashPlanTerms r=reader();TallyLiveService.CashPlanVoucher v=voucher("1","A",1000);v.reference="B";respond(Collections.singletonList(v));List<CashPlanPaymentTerms.Rule> result=r.resolve(Arrays.asList(bill("A","590"),bill("B","590")),Collections.emptyList()).rules;assertEquals(2,result.size());assertTrue(result.stream().allMatch(rule->rule.reviewReason!=null));verify(tally,never()).cashPlanAmounts(anyString(),anyList());}
}
